'use strict';
window.PrepJourney=(()=>{
  const model=window.PrepJourneyModel;
  let entryLevel=null,attempts=[],attemptWorkspace=null,loadedWorkspace=null,loading=false,loadError=false,generation=0;
  const icons={book:'M4 4h7a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4V4Zm16 0h-6M14 7h6v12h-6',code:'m8 7-5 5 5 5m8-10 5 5-5 5m-3-13-2 16',compass:'m16 8-3 5-5 3 3-5 5-3ZM12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Z',check:'m5 12 4 4L19 6',layers:'m12 3 10 6-10 6L2 9l10-6Zm-9 11 9 5 9-5M3 18l9 5 9-5',mic:'M12 3a3 3 0 0 0-3 3v6a3 3 0 0 0 6 0V6a3 3 0 0 0-3-3ZM5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z',play:'m9 5 11 7-11 7V5Z',clock:'M12 7v5l3 2M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Z'};
  const icon=name=>`<svg class="journey-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.book}"/></svg>`;
  const stageIcons={foundations:'book',guided:'code',independent:'compass',depth:'layers',mastery:'mic'};
  const ready=()=>window.PrepPilotUI.workspaceReady?.()===true;
  const savedProfile=()=>state.learningJourney?.version===1?model.profile(state.learningJourney):null;
  const entry=()=>Object.hasOwn(model.levels,route().query.get('level'))?route().query.get('level'):entryLevel||(ready()?savedProfile()?.level:null)||'beginner';
  function itemFor(id,p){const original=baseData.find(item=>item.id===id);if(!original)return null;const variant=window.PREP_LANGUAGES?.[p.language]?.[id]||window.LANGUAGE_CONTENT?.[p.language]?.[id];return original.type==='concept'?window.ConceptAvailability.materialize(original,p.language,variant):{...original,...variant};}
  function stages(p){return model.curriculum(p).map(stage=>({...stage,tasks:stage.tasks.filter(task=>!!itemFor(task.id,p))}));}
  function evidence(){return {reviewed:state.reviewed,tutorialProgress:state.javaTutorialProgress,tutorialCatalogue:baseData.filter(item=>item.tutorial),reflections:state.journeyReflections,readiness:state.journeyReadiness,attempts:ready()&&attemptWorkspace===state.pilotWorkspaceKey?attempts:[],catalogue:window.PILOT_CATALOGUE,historyState:loadError?'unavailable':loading||attemptWorkspace!==state.pilotWorkspaceKey||loadedWorkspace!==state.pilotWorkspaceKey?'loading':'ready'};}
  function taskHref(task,p){if(p.language==='java'&&model.tutorialFor[task.id])return '#/lesson/'+model.tutorialFor[task.id]+'?language=java&round=technical';const item=itemFor(task.id,p),params=new URLSearchParams({language:p.language,domain:task.kind==='coding'?(item?.domain==='Shared'?'All domains':item?.domain||'Investment Banking'):'All domains',role:task.kind==='rehearsal'?p.role:'all'});if(task.kind==='coding'){params.set('round','coding');params.set('question',task.id);return '#/lab?'+params;}if(task.round)params.set('round',task.round);return '#/lesson/'+task.id+'?'+params;}
  function status(task,p){return model.taskStatus(task,p,evidence());}
  function next(p){return model.recommend(stages(p),p,evidence());}
  function roadPreview(level){const existing=ready()?savedProfile():null;if(existing)return progressMap(existing,'home');const p=model.profile({level}),path=stages(p),active=model.levels[level].stage;return `<div class="journey-map" aria-label="Five-stage learning journey"><div class="journey-map-head"><span>Your path, made clear</span><span class="journey-map-tag">5 stages</span></div><div class="journey-map-route">${path.map(stage=>`<div class="journey-map-step ${stage.id===active?'is-current':''}"><span class="journey-node">${icon(stageIcons[stage.id])}</span><div><strong>${stage.short}</strong><span>${{foundations:'Understand the ideas',guided:'Learn by working through examples',independent:'Solve before revealing the answer',depth:'Reason about the trade-offs',mastery:'Explain, reflect and rehearse'}[stage.id]}</span></div>${stage.id===active?'<small>Your starting point</small>':''}</div>`).join('')}</div><div class="journey-map-footer">${icon('spark')}Small steps. Increasing independence.</div></div>`;}
  function home(){
    const p=ready()?savedProfile():null,recommendation=p?next(p):null,level=entry(),customize=p&&level!==p.level,verified=(window.PILOT_CATALOGUE||[]).filter(item=>item.verification.status==='verified').length;
    return `<div class="journey-home"><section class="journey-hero"><div class="journey-hero-copy"><span class="journey-eyebrow">A CLEAR PATH TO YOUR NEXT INTERVIEW</span><h1>Start where you are.<br><em>Grow into your<br>next role.</em></h1><p>From your first concept to a thoughtful technical conversation. Build the knowledge, practise the skills and learn to explain your decisions with confidence.</p><div class="journey-start-choice"><span>Where are you starting?</span><div class="journey-level-switch" role="group" aria-label="Choose your starting level">${Object.entries(model.levels).map(([id,value])=>`<button data-journey-level="${id}" aria-pressed="${id===level}">${value.name}</button>`).join('')}</div><p id="journey-level-description">${model.levels[level].description}</p></div><div class="journey-hero-actions"><a class="button primary large" href="${p?(customize?'#/learn?setup=1&level='+level:'#/learn'):'#/learn?level='+level}">${icon(p?'play':'compass')}${p?(customize?'Update my starting point':'Continue my journey'):'Build my learning path'}</a><a class="journey-text-link" href="#/concepts">Explore Learn</a></div><div class="journey-hero-assurance"><span>${icon('check')}Free to start</span><span>${icon('check')}Learn at your own pace</span></div></div><div class="journey-hero-art">${roadPreview(level)}<div class="journey-art-note"><span class="journey-note-mark">a → b</span><p><strong>Understanding comes first.</strong><br>Then practice. Then independence.</p></div></div></section>${p?`<section class="journey-resume"><div class="journey-resume-icon">${icon('play')}</div><div><span class="journey-eyebrow">YOUR NEXT SMALL STEP</span><h2>${esc(recommendation?.task.title||'Revisit a skill and try a fresh challenge')}</h2><p>${esc(recommendation?.stage.short||'Keep practising')} · ${languageConfig[p.language].name} · ${esc(roleConfig.find(role=>role.id===p.role)?.name||'Your role')}</p></div><a class="button primary" href="${recommendation?taskHref(recommendation.task,p):'#/learn'}">${recommendation?.task.kind==='coding'?'Open practice':'Continue learning'}</a></section>`:''}<section class="journey-proof" aria-label="What you can prepare"><div><strong>Learn the why</strong><span>Java data structures</span></div><div><strong>Put it into practice</strong><span>${verified} verified Java exercises</span></div><div><strong>Prepare the conversation</strong><span>All 5 interview rounds</span></div><div><strong>Bring your context</strong><span>6 domains · 7 role paths</span></div></section><section class="journey-section"><div class="journey-section-heading"><div><span class="journey-eyebrow">A LITTLE STRUCTURE GOES A LONG WAY</span><h2>Know what to learn.<br>Know what to do next.</h2></div><p>A collection of questions can be overwhelming. Follow a connected journey that builds on what you already understand.</p></div><div class="journey-method-grid"><article class="journey-method-feature"><span class="journey-feature-icon">${icon('book')}</span><h3>Make the idea click.</h3><p>Short explanations, explorable methods and examples with input and output. Change an input, predict a result and check your understanding.</p><div class="journey-mini-lesson"><div><span>Input</span><code>price = 100.25<br>quantity = 10</code></div><span class="journey-mini-equals">×</span><div><span>The idea</span><strong>A notional is<br>price × quantity.</strong></div></div><a class="journey-text-link" href="#/concepts">Start learning</a></article><article class="journey-method-card"><span class="journey-feature-icon">${icon('code')}</span><h3>Get support. Then use less of it.</h3><p>Start with small tasks and progressive hints. Work towards an independent attempt before opening the worked answer.</p><a class="journey-text-link" href="#/lab?round=coding">Try Practice</a></article><article class="journey-method-card"><span class="journey-feature-icon">${icon('mic')}</span><h3>Learn to explain your thinking.</h3><p>Practise clarifying a prompt, justifying a decision and discussing risk. Use truthful examples to make the conversation your own.</p><a class="journey-text-link" href="#/rounds">Explore interview rounds</a></article></div></section><section class="journey-round-band"><div><span class="journey-eyebrow">BEYOND GETTING THE CODE RIGHT</span><h2>One journey.<br>Every interview round.</h2><p>Prepare your introduction, your solution and the conversations around them.</p></div><div class="journey-round-list">${roundConfig.map(round=>`<a href="#/round/${round.id}"><span>${round.name}</span><small>${round.label}</small>${icon(round.id==='coding'?'code':'mic')}</a>`).join('')}</div></section><section class="journey-section journey-library"><div class="journey-section-heading"><div><span class="journey-eyebrow">MAKE IT RELEVANT TO YOU</span><h2>Your role. Your language. Your context.</h2></div><p>Foundations come first. Domain scenarios and role-specific questions help you apply them.</p></div><div class="journey-explore-links"><a href="#/domains">${icon('layers')}<span><strong>Explore domains</strong><small>Banking, commerce, AI, cloud and data</small></span></a><a href="#/languages">${icon('code')}<span><strong>Choose a language</strong><small>Java data structures; 4 coding languages</small></span></a><a href="#/roles">${icon('compass')}<span><strong>Find your role</strong><small>Engineering, quality and leadership</small></span></a></div><p class="journey-coverage-note">Automated coding checks currently focus on banking Java. Python, JavaScript and TypeScript have manual practice runners. Every track shows its available material.</p></section><section class="journey-bottom"><span class="journey-eyebrow">YOU DO NOT NEED TO KNOW EVERYTHING TO BEGIN</span><h2>Just take the next useful step.</h2><p>Choose your starting point. We’ll help you find it.</p><a class="button primary large" href="${p?'#/learn?setup=1&level='+level:'#/learn?level='+level}">${icon('compass')}${p?'Adjust my learning path':'Build my learning path'}</a></section></div>`;
  }
  function setup(){const existing=savedProfile(),p=model.profile({language:state.conceptLanguage,domain:currentDomain,role:currentRole,...existing,level:route().query.has('level')?entry():existing?.level||entry()}),session=model.session(p.minutes);return `<div class="journey-setup"><a class="back-link" href="${existing?'#/learn':'#/'}">${existing?'Back to my path':'Back to overview'}</a><div class="journey-page-heading"><span class="journey-eyebrow">LET’S FIND YOUR STARTING POINT</span><h1>A path that meets you<br>where you are.</h1><p>Choose your starting point and focus. You can revisit the basics or jump ahead at any time.</p></div><form id="journey-form" class="journey-onboarding"><fieldset><legend>How does interview preparation feel right now?</legend><div class="journey-level-options">${Object.entries(model.levels).map(([id,value])=>`<label><input type="radio" name="level" value="${id}" ${p.level===id?'checked':''}><span>${icon(id==='beginner'?'book':id==='intermediate'?'code':'compass')}<strong>${value.name}</strong><small>${value.description}</small></span></label>`).join('')}</div></fieldset><div class="journey-form-fields"><label>Concept language<select name="language" id="journey-language">${['java','python'].map(id=>`<option value="${id}" ${p.language===id?'selected':''}>${languageConfig[id].name}</option>`).join('')}</select></label><label>Target role<select name="role" id="journey-role">${roleConfig.map(role=>`<option value="${role.id}" ${p.role===role.id?'selected':''}>${esc(role.name)}</option>`).join('')}</select></label><label>Domain focus<select name="domain" id="journey-domain">${domains.map(domain=>`<option ${p.domain===domain?'selected':''}>${esc(domain)}</option>`).join('')}</select></label><label>Time for a typical session<select name="minutes" id="journey-minutes">${[20,40,60].map(minutes=>`<option value="${minutes}" ${p.minutes===minutes?'selected':''}>About ${minutes} minutes</option>`).join('')}</select></label></div><div class="journey-form-footer"><p>${icon('check')}Changing your path preserves existing code drafts and learning records.</p><button class="button primary large" type="submit">${icon('compass')}${existing?'Update my learning path':'Create my learning path'}</button></div></form>${existing?'<div class="journey-clear-path"><button class="journey-text-button" data-journey-clear>Remove this path</button><span>Lessons, code drafts, reflections and attempts are kept.</span></div>':''}<div class="journey-setup-note"><strong>A starting point, not a test.</strong><p>Your choice changes the recommended starting stage. Earlier stages stay available, and jumping ahead does not mark them complete. Your path and reflections are saved in this browser.</p></div></div>`;}
  function taskCard(task,p){const progress=status(task,p),item=itemFor(task.id,p),spec=p.language==='java'?(window.PILOT_CATALOGUE||[]).find(x=>x.id===task.id):null,manual=task.kind==='coding'&&!spec,key=model.reflectionKey(p,task),reflection=state.journeyReflections?.[key],name=task.kind==='concept'?(item.programming?languageConfig[p.language].name+' concept':'Interview / domain concept'):task.kind==='coding'?(spec?'Java · Automated contract checks':languageConfig[p.language].name+' · Manual practice'):roundFor(task.round).name;return `<article class="journey-task ${progress.done?'is-complete':''}" data-journey-task="${task.id}"><div class="journey-task-icon">${icon(progress.done?'check':task.kind==='concept'?'book':task.kind==='coding'?'code':'mic')}</div><div class="journey-task-main"><div class="journey-task-meta"><span>${esc(name)}</span><span>About ${task.minutes} min</span></div><h3>${esc(task.title)}</h3><p>${task.kind==='concept'?'Read the idea, predict an output and explain it in your own words.':task.kind==='coding'?(task.independent?'Attempt the contract before opening hints or the answer. Check the boundaries and explain your decisions.':'Clarify the example, attempt a solution and use the next hint when you need it.'):'Rehearse aloud using your own experience. State your assumptions and reflect on what you would improve.'}</p><div class="journey-task-actions"><a class="button ${progress.done?'':'primary'}" href="${taskHref(task,p)}">${task.kind==='concept'?'Open lesson':task.kind==='coding'?'Open coding practice':'Open rehearsal question'}</a><span class="journey-task-status" data-source="${progress.source}">${progress.done?icon('check'):''}${esc(progress.label)}</span></div>${task.kind!=='concept'?`<details class="journey-reflection"><summary>${reflection?.note?'My reflection':'Reflect on this step'}</summary><label for="reflection-${task.id}">${manual?'Which cases did you check, and what would you improve?':task.kind==='rehearsal'?'What did you explain well, and what will you change next time?':'Why does your approach work, and which trade-off matters?'}</label><textarea id="reflection-${task.id}" data-journey-note="${task.id}" rows="3" maxlength="3000" placeholder="Write a short reflection in your own words…">${esc(reflection?.note||'')}</textarea><div class="journey-reflection-actions">${progress.source==='reflection'?`<button class="button small" data-journey-record="${task.id}">${progress.done?'Reopen this step':task.kind==='coding'?'Record my self-review':'Record my rehearsal'}</button>`:''}<span data-reflection-status="${task.id}" role="status">${reflection?.note?'Saved in this browser':'Your reflection stays in this browser.'}</span></div>${manual?'<small>Manual practice is self-reviewed. It does not receive an automated contract grade.</small>':''}</details>`:''}</div></article>`;}
  function path(){if(!ready()&&state.learningJourney)return `<div class="journey-loading" role="status">Loading your learning workspace…</div>`;const p=savedProfile();if(!p||route().query.get('setup')==='1')return setup();const path=stages(p),recommended=next(p),requested=route().query.get('stage'),stage=path.find(s=>s.id===requested)||recommended?.stage||path[0],all=path.flatMap(s=>s.tasks),done=all.filter(task=>status(task,p).done),role=roleConfig.find(role=>role.id===p.role),rhythm=model.session(p.minutes);return `<div class="journey-workspace"><header class="journey-workspace-header"><div><span class="journey-eyebrow">YOUR NEXT STEP HAS A PLACE TO LEAD</span><h1>My learning path</h1><p>${languageConfig[p.language].name} · ${esc(role.name)} · ${esc(p.domain)}</p></div><a class="button" href="#/learn?setup=1">Adjust my path</a></header>${progressSummary(p)}<div class="journey-layout"><aside class="journey-sidebar"><div class="journey-path-summary"><span class="journey-eyebrow">YOUR LEARNING JOURNEY</span><strong>${done.length}<span> / ${all.length} steps recorded</span></strong><progress value="${done.length}" max="${all.length}" aria-label="Learning steps recorded">${done.length} of ${all.length}</progress><p>Reading reviews, contract checks and rehearsals are tracked separately.</p></div><nav aria-label="Learning stages">${path.map(s=>{const count=s.tasks.filter(task=>status(task,p).done).length;return `<a href="#/learn?stage=${s.id}" class="journey-stage-link ${s.id===stage.id?'is-active':''}" ${s.id===stage.id?'aria-current="step"':''}>${icon(stageIcons[s.id])}<span><strong>${s.short}</strong><small>${count} of ${s.tasks.length} steps recorded</small></span>${count===s.tasks.length?icon('check'):''}</a>`;}).join('')}</nav><div class="journey-session"><span>${icon('clock')}A ${p.minutes}-minute session</span><p>${rhythm.learn} min to learn<br>${rhythm.practise} min to practise<br>${rhythm.reflect} min to reflect</p><small>A suggested rhythm. Split longer tasks across sessions.</small></div><a class="journey-text-link" href="#/prepare">Build a 7, 14 or 28-day calendar</a></aside><div class="journey-stage-content"><section class="journey-stage-heading"><span class="journey-stage-label">${icon(stageIcons[stage.id])}${stage.label}</span><h2>${stage.name}</h2><p>${stage.description}</p><details class="journey-outcomes"><summary>What you are working towards</summary><ul>${stage.outcomes.map(text=>`<li>${icon('check')}${esc(text)}</li>`).join('')}</ul></details></section>${recommended&&recommended.stage.id!==stage.id?`<div class="journey-nudge"><p><strong>Your suggested next step:</strong> ${esc(recommended.task.title)}</p><a class="journey-text-link" href="#/learn?stage=${recommended.stage.id}">View suggested stage</a></div>`:''}${stage.id==='guided'||stage.id==='independent'?`<div class="journey-practice-note">${icon('code')}<p>${p.language==='java'?'Banking Java exercises have automated contract checks.':'Python uses the manual practice runner; review its output and your own tests.'} Core coding examples use trades and orders, while your domain focus shapes the later discussion tasks.</p></div>`:''}<div class="journey-task-list">${stage.tasks.map(task=>taskCard(task,p)).join('')}</div><section class="journey-stage-close"><h3>Before you move on</h3><p>Explain one idea without looking at the answer. Give a concrete example, name an edge case and say what you would verify.</p>${path.indexOf(stage)<path.length-1?`<a class="button" href="#/learn?stage=${path[path.indexOf(stage)+1].id}">Explore the next stage</a>`:'<a class="button" href="#/evidence">Review my coding evidence</a>'}</section><p class="journey-evidence-note">${loadError?'Execution history could not be loaded. Learning and self-review remain available. ':''}A recorded step is a review, a rehearsal or a problem-specific check. Coding evidence uses up to 200 recent saved attempts. Recorded steps do not certify expertise or predict an interview outcome. Assistance is browser-recorded and self-reported.</p><button class="journey-text-button" data-journey-refresh>Refresh coding evidence</button></div></div></div>`;}
  function lessonGuide(item){const p=ready()?savedProfile():null;if(!p||item.programming&&item.language!==p.language)return '';const stage=stages(p).find(stage=>stage.tasks.some(task=>task.id===item.id));return stage?`<div class="journey-context"><span>${icon(stageIcons[stage.id])}My learning path <span>/</span> ${stage.short}</span><a href="#/learn?stage=${stage.id}">Back to my path</a></div>`:'';}
  function snapshot(p){return model.progress(p,stages(p),evidence());}
  function progressMap(p,mode='full'){
    const result=snapshot(p),labels=stage=>stage.complete?'Completed':stage.id===result.current?'You are here':stage.done?'In progress':'Not started';
    if(mode==='home')return `<div class="journey-map progress-home-map"><div class="journey-map-head"><span>Your progress path</span><span class="journey-map-tag">${result.done} / ${result.total} steps</span></div><div class="journey-map-route">${result.milestones.map(stage=>`<a class="journey-map-step ${stage.id===result.current?'is-current':''}" href="#/learn?stage=${stage.id}"><span class="journey-node">${icon(stage.complete?'check':stageIcons[stage.id])}</span><div><strong>${stage.short}</strong><span>${stage.done} of ${stage.total} steps recorded</span></div><small>${labels(stage)}</small></a>`).join('')}<a class="journey-map-step progress-home-end ${result.ready?'is-ready':''}" href="#/progress"><span class="journey-node">${icon(result.ready?'check':'spark')}</span><div><strong>Interview readiness</strong><span>${result.ready?'Your path checkpoints are met':result.state==='mock_ready'?'Complete your full mock checkpoint':result.label}</span></div></a></div><a class="journey-map-footer" href="#/progress">${icon('compass')}See my progress and remaining gaps</a></div>`;
    return roadMap(p,result);
  }
  function roadMap(p,result,preview=false){
    const position=model.roadPosition(result);
    const names=[['Foundations'],['Guided','practice'],['Independent','coding'],['Technical','depth'],['Interview','rehearsal'],['Interview-ready','target']];
    const desktop={box:'0 0 1200 450',start:[65,310],nodes:[[165,310],[350,170],[535,310],[720,170],[905,310],[1100,170]],paths:['M65 310 L165 310','M165 310 C235 310 280 170 350 170','M350 170 C420 170 465 310 535 310','M535 310 C605 310 650 170 720 170','M720 170 C790 170 835 310 905 310','M905 310 C975 310 1030 170 1100 170']};
    const mobile={box:'0 0 360 1040',start:[110,95],nodes:[[110,215],[250,365],[110,515],[250,665],[110,815],[250,965]],paths:['M110 95 L110 215','M110 215 C110 285 250 295 250 365','M250 365 C250 435 110 445 110 515','M110 515 C110 585 250 595 250 665','M250 665 C250 735 110 745 110 815','M110 815 C110 885 250 895 250 965']};
    function canvas(layout,kind){
      const full=layout.paths.join(' '),current=position.index,origin=current===0?layout.start:layout.nodes[current-1],id='progress-road-'+kind;
      return `<svg class="progress-road-canvas road-canvas-${kind}" data-road-index="${current}" viewBox="${layout.box}" role="group" aria-labelledby="${id}-title ${id}-description"><title id="${id}-title">Road from Start to the Interview-ready target</title><desc id="${id}-description">${preview?'Preview of the preparation road. Create a learning path to track your own progress.':`Your current focus is ${result.currentName}. ${result.done} of ${result.total} learning steps are recorded. The target is reached only when all readiness checkpoints are met.`}</desc><path class="road-edge" d="${full}" pathLength="100"/><path class="road-surface" d="${full}" pathLength="100"/>${layout.paths.map((d,n)=>`<path class="road-travelled" data-road-segment="${n}" d="${d}" pathLength="100" stroke-dasharray="${position.segments[n]*100} 100" ${position.segments[n]===0?'visibility="hidden"':''}/>`).join('')}<path class="road-centre-line" d="${full}"/><g class="road-start" transform="translate(${layout.start.join(' ')})"><circle r="7"/><text x="${kind==='mobile'?-25:-3}" y="${kind==='mobile'?6:40}" text-anchor="${kind==='mobile'?'end':'middle'}">START</text></g>${layout.nodes.map(([x,y],n)=>{
        const stage=result.milestones[n],complete=stage?stage.complete:result.ready,active=n===current&&!result.ready,state=complete?'complete':active?'current':'pending',href=stage?'#/learn?stage='+stage.id:'#/progress',counts=stage?`${stage.done} / ${stage.total} recorded`:result.ready?'Target reached':`${result.criteriaMet} / ${result.criteriaTotal} criteria`,labelX=kind==='mobile'?(x<180?170:190):x,labelY=kind==='mobile'?y-14:y+(y>200?55:-74),anchor=kind==='mobile'?(x<180?'start':'end'):'middle',status=complete?'Completed':active?'Current milestone':'To come',title=names[n].join(' ');
        return `<a href="${href}" ${stage?'':'data-open-mock'} class="road-milestone" style="--road-stop-order:${n}" data-state="${state}" aria-label="${title}: ${status}. ${counts}" ${active?'aria-current="step"':''} tabindex="0"><title>${title}: ${status}. ${counts}</title><circle class="road-stop-halo" cx="${x}" cy="${y}" r="30"/><circle class="road-stop-circle" cx="${x}" cy="${y}" r="23"/><g class="road-stop-symbol" transform="translate(${x-10} ${y-10}) scale(.84)"><path d="${complete?icons.check:stage?icons[stageIcons[stage.id]]:'M5 22V2M5 3h14l-4 5 4 5H5'}"/></g><text class="road-stop-name" x="${labelX}" y="${labelY}" text-anchor="${anchor}">${names[n].map((line,j)=>`<tspan x="${labelX}" dy="${j?21:0}">${line}</tspan>`).join('')}<tspan class="road-stop-count" x="${labelX}" dy="24">${counts}</tspan>${active&&!preview?`<tspan class="road-current-caption" x="${labelX}" dy="18">Current milestone</tspan>`:''}</text></a>`;
      }).join('')}<path data-road-active d="${layout.paths[current]}" fill="none" stroke="none"/><g data-road-marker data-fraction="${position.fraction}" class="road-user-marker" transform="translate(${origin.join(' ')})"><g class="road-user-bubble"><rect x="-56" y="-76" width="112" height="29" rx="8"/><path d="m-6-47 6 8 6-8"/><text x="0" y="-57" text-anchor="middle">${preview?'Start here':result.ready?'Target reached':'You are here'}</text></g><circle class="road-candidate-halo" r="26"/><g class="road-candidate" aria-hidden="true"><path class="candidate-leg candidate-leg-left" d="m-4 8-2 13h-4"/><path class="candidate-leg candidate-leg-right" d="m4 8 2 13h4"/><path class="candidate-jacket" d="M-6-6h12l3 15H-9l3-15Z"/><path class="candidate-shirt" d="m-3-6 3 9 3-9Z"/><path class="candidate-arm" d="m-6-3-7 9"/><path class="candidate-arm candidate-hand" d="m6-3 7 9"/><rect class="candidate-case" x="-18" y="7" width="9" height="8" rx="1.5"/><path class="candidate-case-handle" d="M-16 7V5h5v2"/><circle class="candidate-head" cy="-14" r="6"/><path class="candidate-hair" d="M-6-14c-1-9 13-9 12 0l-4-3-8 3Z"/></g></g></svg>`;
    }
    return `<section class="progress-road" aria-labelledby="progress-road-heading"><div class="progress-road-heading"><div><span class="journey-eyebrow">${preview?'YOUR ROAD AHEAD':'YOUR ROAD TO THE INTERVIEW'}</span><h2 id="progress-road-heading">From your first step to interview-ready.</h2><p>${preview?'Create a path to move your candidate with your own recorded work.':'Your candidate follows your recorded progress. Select a milestone to see its next steps.'}</p></div><div class="progress-road-actions"><div><button class="button" data-road-replay>Replay animation</button>${preview?'':'<button class="button" data-road-locate>Find my position</button>'}</div><span data-road-motion-note hidden>Reduced motion is on</span></div></div>${canvas(desktop,'desktop')}${canvas(mobile,'mobile')}<div class="road-legend"><span><i class="road-key-complete"></i>Recorded progress</span><span><i class="road-key-current"></i>${preview?'Starting point':'Your current milestone'}</span><span><i class="road-key-pending"></i>Road ahead</span><strong>${result.ready?'Your readiness target is met':preview?'Start when you are ready':result.currentName+' is your current focus'}</strong></div></section>`;
  }
  function placeRoadMarkers(){const p=savedProfile();window.PrepRoadMotion?.mount({scope:JSON.stringify([state.pilotWorkspaceKey||'preview',p?model.readinessKey(p,window.PILOT_CATALOGUE):'preview'])});}
  window.addEventListener?.('resize',placeRoadMarkers);
  document.addEventListener('click',event=>{if(event.target.closest('[data-road-replay]'))window.PrepRoadMotion?.replay();if(!event.target.closest('[data-road-locate]'))return;const marker=[...(document.querySelectorAll('[data-road-marker]')||[])].find(item=>item.closest('svg').getBoundingClientRect().width>0);marker?.scrollIntoView({block:'center'});});
  function progressSummary(p){const result=snapshot(p);return `<section class="progress-summary" data-readiness-state="${result.state}" aria-label="Current progress and readiness"><div>${icon(result.ready?'check':'compass')}<span><small>${result.ready?'YOUR CHECKPOINTS ARE MET':'YOUR CURRENT PROGRESS'}</small><strong>${result.ready?result.label:result.currentName}</strong></span></div><p><strong>${result.done} of ${result.total}</strong> steps recorded · ${result.criteriaMet} of ${result.criteriaTotal} readiness criteria met</p><a class="button" href="#/progress">View progress & readiness</a></section>`;}
  function criteriaList(p,result){return `<section class="readiness-panel" aria-labelledby="readiness-criteria-title"><div class="progress-section-heading"><div><span class="journey-eyebrow">WHAT NEEDS TO BE IN PLACE</span><h2 id="readiness-criteria-title">Your interview checkpoints</h2></div><span>${result.criteriaMet} of ${result.criteriaTotal} met</span></div><ul class="readiness-criteria">${result.milestones.map(stage=>`<li data-met="${stage.complete}"><span class="readiness-criterion-icon">${icon(stage.complete?'check':stageIcons[stage.id])}</span><div><h3>${stage.short}</h3><p>${stage.done} of ${stage.total} steps recorded. ${stage.complete?'Stage checkpoints are met.':stage.tasks.find(task=>!task.status.done)?.title+' remains.'}</p><small>${stage.id==='independent'||stage.id==='depth'?(p.language==='java'?'Independent coding milestones need current full checks with no recorded assistance.':'Python coding milestones use your own tests and explicit self-review.'):'Lesson reviews and interview rehearsals are self-reported.'}</small></div><a class="journey-text-link" href="#/learn?stage=${stage.id}">${stage.complete?'Review stage':'Work on this'}</a></li>`).join('')}<li data-met="${result.mockComplete}"><span class="readiness-criterion-icon">${icon(result.mockComplete?'check':'mic')}</span><div><h3>Full mock interview</h3><p>${result.mockComplete?'Your full-mock self-assessment is recorded.':'Rehearse all five rounds and record what went well and what to improve.'}</p><small>Self-assessed communication and confidence; no automated interview grading.</small></div><button class="journey-text-button" data-open-mock>${result.mockComplete?'View record':'Record a mock'}</button></li></ul></section>`;}
  function mockForm(p,result){const record=result.record||{},locked=model.validMock(record),prompts={introduction:'I can introduce my experience with a focused, truthful example.',coding:'I can solve a coding prompt and explain it without consulting an answer.',technical:'I can discuss trade-offs, failure cases and meaningful tests.',manager:'I can explain a stakeholder decision and the risk behind it.',hr:'I can discuss motivation, development and questions for the team.'};return `<details class="readiness-mock readiness-panel" id="readiness-mock" ${result.practiceComplete||record.strengths?'open':''}><summary>${icon('mic')}Full mock interview checkpoint<span>${locked?'Recorded':'Self-assessment'}</span></summary><div class="readiness-mock-body"><p>Rehearse the introduction, coding, technical, stakeholder and HR conversations in one session. Then record your own assessment. You can practise this before finishing the path; the remaining checkpoints still need to be met.</p><form id="readiness-form"><fieldset><legend>After your mock, confirm each area you can handle.</legend><div class="readiness-self-checks">${model.mockChecks.map(id=>`<label><input type="checkbox" name="round" value="${id}" ${(record.checks||[]).includes(id)?'checked':''} ${locked?'disabled':''} required><span><strong>${roundFor(id).short} round</strong>${prompts[id]}</span></label>`).join('')}</div></fieldset><div class="readiness-reflection-fields"><label>What went well?<textarea name="strengths" rows="4" minlength="40" maxlength="3000" required ${locked?'readonly':''} placeholder="Describe a concrete example of something you explained or solved well…">${esc(record.strengths||'')}</textarea><small>At least 40 characters. This records your reflection; it does not grade its quality.</small></label><label>What will you improve next?<textarea name="improvements" rows="4" minlength="40" maxlength="3000" required ${locked?'readonly':''} placeholder="Name a gap, an edge case or a follow-up you want to handle better…">${esc(record.improvements||'')}</textarea><small>Choose a specific next action, even when the mock went well.</small></label></div>${locked?`<div class="readiness-saved"><span>${icon('check')}Recorded ${esc(new Date(record.recordedAt).toLocaleDateString('en-GB'))} · self-assessment</span><button class="button" type="button" data-readiness-reopen>Reopen checkpoint</button></div>`:`<label class="readiness-confirm"><input type="checkbox" name="mockCompleted" value="yes" required><span>I completed a full mock and these checks describe my own practice.</span></label><button class="button primary" type="submit">Record my mock interview</button>`}<p id="readiness-save-status" role="status">${locked?'Your saved self-assessment is part of the readiness checkpoint.':'Drafts and the final record stay in this browser and the current workspace.'}</p></form></div></details>`;}
  function progressView(){
    if(!ready()&&state.learningJourney)return `<div class="journey-loading" role="status">Loading your progress workspace…</div>`;
    const p=savedProfile();
    if(!p)return `<div class="progress-page"><header class="progress-page-heading"><span class="journey-eyebrow">PROGRESS YOU CAN UNDERSTAND</span><h1>Know where you are.<br>See what comes next.</h1><p>Create a learning path to track your current stage and see the checkpoints for interview preparation.</p></header><div class="progress-road-preview" aria-label="Your progress path preview">${roadMap(model.profile(),model.progress(model.profile(),stages(model.profile()),{catalogue:window.PILOT_CATALOGUE,historyState:'ready'}),true)}</div><section class="progress-empty"><h2>Start with your own preparation path.</h2><p>Your progress will use reviewed lessons, coding results and recorded rehearsals. Choosing an advanced starting point will not mark earlier stages complete.</p><a class="button primary large" href="#/learn">Create my learning path</a></section></div>`;
    const result=snapshot(p),role=roleConfig.find(role=>role.id===p.role),nextStep=model.recommend(stages(p),{...p,level:'beginner'},evidence()),headline=result.ready?'You have met this path’s preparation checkpoints.':result.state==='mock_ready'?'Put it together in a full mock interview.':result.historyKnown?'Here is your current preparation progress.':'Let’s verify your coding evidence.';
    return `<div class="progress-page" data-readiness-state="${result.state}"><header class="progress-page-heading"><div><span class="journey-eyebrow">YOUR PREPARATION, WITH CONTEXT</span><h1>My progress & readiness</h1><p>${languageConfig[p.language].name} · ${esc(role?.name||'Your role')} · ${esc(p.domain)}${p.company?' · '+esc(p.company):''}</p></div><a class="button" href="#/learn">Open my learning path</a></header><section class="readiness-banner" data-readiness-state="${result.state}"><span class="readiness-banner-icon">${icon(result.ready?'check':result.state==='mock_ready'?'mic':'compass')}</span><div><span class="readiness-status-label" data-readiness-label>${result.label}</span><h2>${headline}</h2><p>${result.ready?'This means the selected plan’s practice checkpoints and your full-mock self-assessment are recorded. It is not a prediction of an employer’s decision.':result.historyKnown?'Your position is based on recorded work. Opening a later stage or choosing an advanced starting point does not move this marker.':loadError?'Refresh your connection to verify saved coding results. Missing evidence is not treated as an incorrect solution.':'The current coding checks are being refreshed before readiness is confirmed.'}</p></div><div class="readiness-banner-count"><strong>${result.criteriaMet}<span> / ${result.criteriaTotal}</span></strong><span>criteria met</span></div></section>${progressMap(p)}<div class="progress-overview"><article><span>${icon('compass')}You are here</span><strong>${result.currentName}</strong><p>${result.ready?'All path checkpoints are met. Continue with fresh practice.':result.practiceComplete?'Your learning stages are complete. Record the final full-mock checkpoint.':'The earliest stage with an unmet checkpoint. Later work is still recorded.'}</p></article><article><span>${icon('check')}Work recorded</span><strong>${result.done} of ${result.total} steps</strong><p>${result.selfReviewed} concepts reviewed · ${result.checked} coding milestones checked · ${result.rehearsed} rehearsals recorded</p></article><article><span>${icon('clock')}Suggested workload remaining</span><strong>${result.sessions?`About ${result.sessions} sessions`:'Practice target complete'}</strong><p>${result.sessions?`At ${p.minutes} minutes per session, using the listed task estimates. This is a planning estimate.`:'Revisit your gaps and repeat a full mock before your next interview.'}</p></article></div>${!result.missing.length&&result.gradingAvailable?'':`<div class="progress-evidence-notice">Some required material or assessment evidence is unavailable. Readiness remains pending until it can be reviewed.</div>`}<div class="progress-dashboard"><div>${criteriaList(p,result)}${mockForm(p,result)}</div><aside class="progress-next"><span class="journey-eyebrow">YOUR NEXT USEFUL STEP</span><h2>${result.practiceComplete?(result.mockComplete?'Keep the practice fresh':'Rehearse the full conversation'):esc(nextStep?.task.title||'Review the remaining checkpoints')}</h2><p>${result.practiceComplete?'A full mock helps connect what you know to what you can explain. Keep noting questions that need another attempt.':esc(nextStep?.stage.description||'Review each stage to see which evidence is still needed.')}</p>${result.practiceComplete?'<button class="button primary" data-open-mock>Open mock checkpoint</button>':`<a class="button primary" href="${nextStep?taskHref(nextStep.task,p):'#/learn'}">${nextStep?.task.kind==='coding'?'Open coding practice':'Continue preparation'}</a>`}<div class="progress-evidence-types"><h3>What the evidence means</h3><p><strong>Concepts:</strong> your explicit lesson reviews.</p><p><strong>Java coding:</strong> current full contract checks; independent milestones require no recorded help.</p><p><strong>Other languages:</strong> manual execution and your own self-review.</p><p><strong>Interview rounds:</strong> your rehearsal reflections and final self-assessment.</p></div><a class="journey-text-link" href="#/evidence">Inspect coding attempt history</a><button class="journey-text-button" data-journey-refresh>Refresh coding evidence</button></aside></div><details class="progress-policy"><summary>How interview readiness is decided</summary><p>The five learning stages must have their required steps recorded, and all five areas of the full mock must be confirmed with a strengths reflection and an improvement reflection. The evidence score above gives each stage and the full mock an equal share. It summarises recorded preparation; the checkpoints below determine whether the path is complete.</p><p>Automated coding evidence checks the current Java problem version and its full contract. Reviews, communication and mock confidence are self-assessed. Non-Java readiness is labelled self-assessed because those coding runners have no automated contract grading.</p><p>The checkpoint is specific to the selected language, role and domain. A changed problem contract requires current evidence. Up to 200 recent saved attempts are used. You can reopen the mock checkpoint whenever your assessment changes.</p></details></div>`;
  }
  function mockRecord(form,p,confirmed=false){return {checks:new FormData(form).getAll('round').filter(id=>model.mockChecks.includes(id)),strengths:form.elements.strengths.value.slice(0,3000),improvements:form.elements.improvements.value.slice(0,3000),confirmed,recordedAt:confirmed?new Date().toISOString():null};}
  document.addEventListener('submit',event=>{if(event.target.id!=='readiness-form')return;event.preventDefault();const p=ready()?savedProfile():null;if(!p)return;const record=mockRecord(event.target,p,new FormData(event.target).get('mockCompleted')==='yes');if(!model.validMock(record)){document.getElementById('readiness-save-status').textContent='Confirm all five rounds and add at least 40 non-blank characters to each reflection.';return;}state.journeyReadiness??={};state.journeyReadiness[model.readinessKey(p,window.PILOT_CATALOGUE)]=record;persist();render();toast('Full-mock self-assessment recorded. Your readiness checkpoints have been updated.');});
  document.addEventListener('input',event=>{const form=event.target.closest?.('#readiness-form'),p=ready()?savedProfile():null;if(!form||!p)return;const key=model.readinessKey(p,window.PILOT_CATALOGUE);if(model.validMock(state.journeyReadiness?.[key]))return;state.journeyReadiness??={};state.journeyReadiness[key]=mockRecord(form,p,false);const saved=persist();document.getElementById('readiness-save-status').textContent=saved?'Draft saved in this browser. Record your mock when you have finished.':'Browser storage is unavailable. Copy your reflection before leaving.';});
  document.addEventListener('click',event=>{if(event.target.closest('[data-open-mock]')&&route().path==='progress'){event.preventDefault();const details=document.getElementById('readiness-mock');if(details){details.open=true;details.scrollIntoView({block:'start'});details.querySelector('input:not(:disabled),textarea')?.focus({preventScroll:true});}}if(event.target.closest('[data-readiness-reopen]')){const p=ready()?savedProfile():null;if(!p)return;const record=state.journeyReadiness?.[model.readinessKey(p,window.PILOT_CATALOGUE)];if(record){record.confirmed=false;persist();render();toast('Mock checkpoint reopened. Your notes are kept.');}}});
  function install(){publicHome=home;const oldLab=labPage;labPage=()=>{const item=labQuestion().item;return (item?lessonGuide(item):'')+oldLab();};}
  async function mount(){placeRoadMarkers();const selected=document.querySelector('.journey-stage-link.is-active');if(selected){const nav=selected.parentElement;if(nav.scrollWidth>nav.clientWidth)nav.scrollLeft=Math.max(0,selected.offsetLeft-nav.offsetLeft-(nav.clientWidth-selected.offsetWidth)/2);}const p=savedProfile(),key=state.pilotWorkspaceKey;if(!['learn','home','progress','track',''].includes(route().path)){loadedWorkspace=null;return;}if(!p||!ready())return;if(attemptWorkspace!==key){attemptWorkspace=key;attempts=[];loadedWorkspace=null;loading=false;loadError=false;generation++;}if(loadedWorkspace===key||loading)return;loadedWorkspace=key;loading=true;const token=++generation;try{const records=await window.PrepPilotUI.learningAttempts();if(token!==generation||key!==state.pilotWorkspaceKey)return;attempts=records;loadError=false;}catch{if(key===state.pilotWorkspaceKey){attempts=[];loadError=true;}}finally{if(token===generation){loading=false;if(['learn','home','progress','track'].includes(route().path))render();}}}
  function currentTask(id){const p=savedProfile();if(!p||!ready())return null;const task=stages(p).flatMap(stage=>stage.tasks).find(task=>task.id===id);return task?{p,task,key:model.reflectionKey(p,task)}:null;}
  document.addEventListener('submit',event=>{if(event.target.id!=='journey-form')return;event.preventDefault();if(!ready()){toast('Your learning workspace is loading. Try again in a moment.');return;}const form=new FormData(event.target),p=model.profile(Object.fromEntries(form));state.learningJourney={...p,createdAt:state.learningJourney?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};state.conceptLanguage=p.language;state.language=p.language;currentLanguage=p.language;currentDomain=p.domain;state.domain=p.domain;currentRole=p.role;state.role=p.role;category='All';refreshLanguageContent();persist();loadedWorkspace=null;go('learn?stage='+model.levels[p.level].stage);render();});
  document.addEventListener('click',event=>{const level=event.target.closest('[data-journey-level]');if(level){entryLevel=level.dataset.journeyLevel;render();document.querySelector(`[data-journey-level="${entryLevel}"]`)?.focus({preventScroll:true});}const record=event.target.closest('[data-journey-record]');if(record){const selected=currentTask(record.dataset.journeyRecord);if(!selected)return;state.journeyReflections??={};const reflection=state.journeyReflections[selected.key]??={note:'',reviewed:false};if(reflection.note.trim().length<20){document.querySelector(`[data-reflection-status="${selected.task.id}"]`).textContent='Write at least 20 characters about what you practised.';document.getElementById('reflection-'+selected.task.id)?.focus();return;}reflection.reviewed=!reflection.reviewed;reflection.updatedAt=new Date().toISOString();persist();render();toast(reflection.reviewed?'Self-review recorded. Return to it whenever you need.':'Step reopened for another practice.');}if(event.target.closest('[data-journey-refresh]')){loadedWorkspace=null;render();}if(event.target.closest('[data-journey-clear]')&&ready()){delete state.learningJourney;entryLevel='beginner';loadedWorkspace=null;persist();go('learn');render();toast('Path removed. Your learning records and code drafts are kept.');}});
  document.addEventListener('input',event=>{const id=event.target.dataset.journeyNote;if(!id)return;const selected=currentTask(id);if(!selected)return;state.journeyReflections??={};const old=state.journeyReflections[selected.key]||{};state.journeyReflections[selected.key]={...old,note:event.target.value.slice(0,3000),reviewed:false,updatedAt:new Date().toISOString()};const saved=persist();document.querySelector(`[data-reflection-status="${id}"]`).textContent=saved?(status(selected.task,selected.p).source==='checks'?'Reflection saved in this browser.':'Draft saved in this browser. Record your self-review when ready.'):'Browser storage unavailable. Copy your reflection before leaving.';});
  document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.journey-explore[open]').forEach(details=>details.open=false);});
  return {install,mount,home,path,progressView,lessonGuide,stages,taskHref,snapshot,evidence,views:{learn:path,progress:progressView}};
})();
